# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.51.0/ankra-cli-darwin-arm64"
      sha256 "fd4747b90f784860df9b52961cc3722a7780821b3f3c7ca0c338293d9998e964"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.51.0/ankra-cli-darwin-amd64"
      sha256 "9e76c935e594fe112f4fd44b7f883875b726db40a7a7780dc17d93aaf5a9e0a2"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.51.0/ankra-cli-linux-arm64"
      sha256 "2d1905d142bd5b731c3740c6d567c0aa89a4950ca1b4ec01df710b8bd4bffa79"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.51.0/ankra-cli-linux-amd64"
      sha256 "3c5f371796d9de116f3091169711211204aac7d691224239abcd0c7729c9158c"
    end
  end

  def install
    # Release assets are bare binaries (no archive), so the download has no
    # execute bit; set it before generating completions runs the binary.
    bin.install Dir["ankra-cli-*"].first => "ankra"
    chmod 0755, bin/"ankra"
    generate_completions_from_executable(bin/"ankra", "completion")
  end

  test do
    assert_match "ankra version v#{version}", shell_output("#{bin}/ankra --version")
  end
end
